export function countNamedCalls(names) {
  function makeCounter() {
    let count = 0;
    return () => ++count;
  }
  const counters = new Map();
  return names.map(name => {
    if (!counters.has(name)) counters.set(name, makeCounter());
    return counters.get(name)();
  });
}
